fn reverse(a: &Vec<i32>) -> Vec<i32> {
    // Pre‐allocate exactly the right amount of space.
    let mut result = Vec::with_capacity(a.len());
    // Iterate the input slice in reverse order, cloning each element into `result`.
    for &val in a.iter().rev() {
        result.push(val);
    }
    result
}

fn main() {
    let empty: Vec<i32> = vec![];
    let rev_empty = reverse(&empty);
    assert_eq!(rev_empty, vec![]);

    let v = vec![1, 2, 3, 4, 5];
    let rev_v = reverse(&v);
    assert_eq!(rev_v, vec![5, 4, 3, 2, 1]);
    
    println!("All tests passed!");
}